const status = $('Check Fathom Status').first().json;
const portfolio = $('Get Portfolio Status').first().json;
const trading = $('Get Trading Status').first().json;

const report = {
  timestamp: new Date().toISOString(),
  system_status: status.status || 'unknown',
  uptime: status.uptime || 'unknown',
  portfolio: {
    total_value_usd: portfolio.portfolio?.total_value_usd || 0,
    holdings_count: portfolio.portfolio?.holdings_count || 0
  },
  safety: {
    daily_loss_pct: trading.today?.loss_current || 0,
    trades_today: trading.today?.trades || 0,
    trades_remaining: trading.today?.trades_remaining || 0,
    trading_halted: trading.trading_halted || false
  },
  health: status.health || {},
  alerts: []
};

if (report.system_status !== 'alive') report.alerts.push('System not alive');
if (report.safety.daily_loss_pct > 10) report.alerts.push('Daily loss exceeds 10%');
if (report.safety.trading_halted) report.alerts.push('Trading halted');
if (report.health.kraken_auth !== 'ok') report.alerts.push('Kraken auth issue');

report.summary = report.alerts.length === 0 ? 'All systems nominal' : report.alerts.length + ' alert(s)';
return [{ json: report }];

const report = $input.first().json;
console.log('=== RHIZ HEALTH REPORT ===');
console.log(JSON.stringify(report, null, 2));
return [{ json: { logged: true, summary: report.summary } }];

